<script setup lang="ts">
import {ref,onBeforeUnmount,watch} from 'vue'
type Snapshot={signal_order:string[];signal_message:string;relay_errors:number;waiting?:boolean}
const props=defineProps<{initial?:Snapshot}>(),emit=defineEmits<{complete:[payload:Snapshot];change:[payload:Snapshot];pulse:[]}>()
const order=['前船','后船','领船'],done=ref<string[]>([...(props.initial?.signal_order||[])]),message=ref(props.initial?.signal_message||''),waiting=ref(props.initial?.waiting||false),note=ref(props.initial?.signal_message?'刚才的号令和复号已保留，接着传清楚。':'先定归队令。前船接令、后船复号，领船确认后才全队行动。'),errors=ref(props.initial?.relay_errors||0),sending=ref(false)
watch([done,message,waiting,errors,sending],()=>emit('change',{signal_order:[...done.value],signal_message:message.value,relay_errors:errors.value,waiting:waiting.value||sending.value}),{deep:true,flush:'sync'})
let timer:ReturnType<typeof setTimeout>
function choose(word:string){if(word!=='归队'){errors.value++;note.value='今夜练的是收队：进攻令会把船引向曹寨。重新选一道令。';return}message.value=word;note.value='把“归队”令先传给前船。'}
function send(name:string){if(!message.value||sending.value||waiting.value||done.value.length===3)return;if(name!==order[done.value.length]){errors.value++;note.value=`${order[done.value.length]}还没有收到。越过它，后面的船就不知道该听谁。`;return}sending.value=true;emit('pulse');note.value=`灯号正传向${name}……`;timer=setTimeout(()=>{sending.value=false;waiting.value=true;note.value=`${name}举灯回应，确认它听到的是哪道令。`},700)}
function acknowledge(word:string){if(!waiting.value)return;if(word!=='归队'){errors.value++;note.value='复号与原令不同，暂不动船；把“归队”再传清楚。';return}done.value.push(order[done.value.length]);waiting.value=false;note.value=done.value.length===3?'前后都应了同一道令。领船可以统一收队。':`${done.value.at(-1)}已复号。接着传给${order[done.value.length]}。`}
function reset(){clearTimeout(timer);done.value=[];waiting.value=false;sending.value=false;message.value='';note.value='先定归队令，再依次传前船、后船、领船。'}
onBeforeUnmount(()=>clearTimeout(timer))
</script>
<template><section class="relay-stage"><div class="relay-scrim"></div><div class="action-heading"><span>军令要传到，也要听见回应</span><h2>雾中复号</h2><p>{{note}}</p></div>
<div v-if="!message" class="flag-rack" aria-label="选择旗令"><button v-for="word in ['归队','进攻','散开']" @click="choose(word)">{{word}}<small>传令旗</small></button></div>
<template v-else><button v-for="(ship,i) in order" :key="ship" class="relay-ship" :class="{received:done.includes(ship),target:order[done.length]===ship,sending:sending&&order[done.length]===ship}" :style="{left:[60.5,37.7,76.7][i]+'%',top:[37.3,54.2,27.7][i]+'%'}" @click="send(ship)" :aria-label="`向${ship}传令`"><i></i><strong>{{ship}}</strong><small>{{done.includes(ship)?'归队 · 已复号':order[done.length]===ship?'传归队令':'等待号令'}}</small></button></template>
<div v-if="waiting" class="relay-ack"><p>{{order[done.length]}}在复号：</p><button @click="acknowledge('归队')">“归队令，收到了！”</button><button @click="acknowledge('近寨')">“继续近寨！”</button></div>
<footer class="action-footer"><button @click="reset">重传这一令</button><span>{{done.length}} / 3 船位已确认</span><button class="gold" :disabled="done.length!==3" @click="emit('complete',{signal_order:[...done],signal_message:'归队',relay_errors:errors})">前后无误，回到甲板</button></footer></section></template>
<style scoped>
.relay-stage{position:absolute;inset:0;background:#07151f url('/v12/signal-fleet.webp') center/cover}.relay-scrim{position:absolute;inset:0;background:linear-gradient(180deg,#06111dd9,transparent 55%,#06111ddd)}.action-heading{position:absolute;top:9%;left:6%;max-width:620px;color:#e5d6b5}.action-heading span{letter-spacing:.2em;font-size:12px}.action-heading h2{font:38px SimSun;margin:14px 0}.action-heading p{line-height:1.7;color:#c4d5d8;max-width:500px}.flag-rack{position:absolute;top:43%;left:12%;display:flex;gap:35px}.flag-rack button{background:#3f3330e8;color:#e7cea0;border:1px solid #ae8e61;padding:32px 24px;writing-mode:vertical-rl;font:28px SimSun;min-height:150px}.flag-rack small{font:11px sans-serif;color:#c3b8a3;margin-top:15px}.relay-ship{position:absolute;transform:translate(-50%,-50%);display:grid;gap:8px;text-align:center;padding:14px;color:#f3dfb8;text-shadow:0 2px 5px #000;background:#0a18278c;border-radius:50%}.relay-ship i{display:block;width:16px;height:24px;background:#f9bc62;box-shadow:0 0 32px #ffb65d;margin:auto;border-radius:4px}.relay-ship small{font-size:12px}.relay-ship.target{outline:1px solid #d9ae6b}.relay-ship.received i{background:#b3ddd2;box-shadow:0 0 30px #9edbc5}.relay-ship.sending i{animation:lantern .35s alternate 4}.relay-ack{position:absolute;bottom:20%;left:6%;padding:20px;border-left:2px solid #d1af70;background:#081724eb}.relay-ack button{border-bottom:1px solid #9d8969;margin:7px 20px 0 0;padding:12px;color:#efe0ba}.action-footer{position:absolute;bottom:5%;left:6%;right:6%;display:flex;align-items:center;gap:24px;justify-content:space-between}.action-footer>button:not(.gold){padding:12px;border-bottom:1px solid #c4ac82}.action-footer span{font-size:12px;color:#bac9cf}.action-footer button:disabled{opacity:.35}@keyframes lantern{to{opacity:.3;transform:scale(.8)}}@media(max-width:700px){.action-heading{top:9%;max-width:85%}.action-heading h2{font-size:28px}.action-footer{flex-wrap:wrap;bottom:3%;gap:10px}.flag-rack{left:10%;gap:15px}.flag-rack button{padding:20px 15px}.relay-ack{bottom:25%;right:6%}.action-heading p{font-size:13px}}@media(prefers-reduced-motion:reduce){.relay-ship.sending i{animation:none}}
</style>
